INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 2, 7, 5118061, 91002, "ペコリーヌとの出会い", 20063115, 1, "青空の下で謁見", 0, 2834);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 2, 7, 5118062, 91002, "マホとの出会い", 20063115, 1, "未来の騎空団\nマスコット？", 0, 2835);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "ランドソル市街地", 40, 8, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 2, 7, 5118063, 91002, "アキノとの出会い", 20063115, 1, "お嬢さまからの\n緊急依頼", 0, 2837);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 2, 18, 5118064, 91002, "ジュンとの出会い", 20063115, 1, "黄金色の悩みごと", 0, 4108402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 2, 18, 5118065, 91002, "カオリとの出会い", 20063115, 1, "白熱！　格闘大会！", 0, 4107402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "オーエド町", 40, 8, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 2, 16, 5118066, 91002, "ニノンとの出会い", 20063115, 1, "祭り太鼓はオーエドの華", 1, 9000227);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 3, 19, 5118067, 91002, "スズナとの出会い", 20063115, 1, "人気者は遅れて\nやってくる", 0, 2101181);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "ランドソル市街地", 40, 8, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 3, 18, 5118068, 91002, "ナナカとの出会い", 20063115, 1, "巫女・ミーツ・魔法少女", 0, 4109402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 3, 18, 5118069, 91002, "キャル＆コッコロとの出会い", 20063115, 1, "ネズ耳は二度なくなる", 0, 4305402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "ランドソル市街地", 40, 8, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 3, 18, 5118070, 91002, "ユカリとの出会い", 20063115, 1, "この出会いにカンパイ！", 0, 4101402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "ランドソル市街地", 40, 8, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 3, 18, 5118071, 91002, "アオイとの出会い", 20063115, 1, "陰陽アンサンブル", 0, 4106402);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, "フリーマーケット会場", 40, 8, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 3, 7, 5118072, 91002, "シノブとの出会い", 20063115, 1, "運試し十番勝負！", 1, 2836);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 0, 0, 0, 0, 1, 0, 5118600, 0, "オープニング", 20063115, 0, "彼女たちの新たな日常", 0, 0);
